cat << 'INNER_EOF' > /tmp/sync_live_system.py
import base64
import os

files = {'src/components/Admin/PaymentConfig.tsx': '', 'src/components/Subscription/SubscriptionGate.tsx': '', 'src/components/CaptivePortal/PaymentModal.tsx': '', 'server/paymentGateway.ts': '', 'server/routes.ts': ''}

for path, content_b64 in files.items():
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'w', encoding='utf-8') as f:
        f.write(base64.b64decode(content_b64).decode('utf-8'))
    print(f"Updated: {path}")

print("All real live files updated successfully!")
INNER_EOF
python3 /tmp/sync_live_system.py
rm -f /tmp/sync_live_system.py
npm run build
pm2 restart all --update-env
pm2 save
